import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r,o,c as a,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const m=JSON.parse('{"title":"Libre NFC","description":"","frontmatter":{},"headers":[],"relativePath":"install/libreNFC.md","filePath":"install/libreNFC.md"}'),n={name:"install/libreNFC.md"};function i(l,e,d,c,p,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<p>These days almost all phones support NFC scanning. If yours does, you can scan your Libre 1, US 14 days, Libre 2/2+ (EU) and Libre Pro sensor with xDrip in addition to the vendor-supplied LibreLink. Please note, xDrip NFC scan <strong>cannot</strong> start a sensor - only LibreLink (or the reader) can do this.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   LibreAlarm</p></div><h2 id="supported-data-sources" tabindex="-1">Supported data sources <a class="header-anchor" href="#supported-data-sources" aria-label="Permalink to &quot;Supported data sources&quot;">​</a></h2><p>In order to access the NFC menu, you need to select one of the Libre data sources.</p><p>If you will only use xDrip to scan the sensor, you should choose LibreAlarm.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>If you enable xDrip NFC scan support, you should disable any other app that will try to read NFC devices in order to avoid conflicts. This is especially true for the Libre vendor app.</p></div><h4 id="configure-nfc" tabindex="-1">Configure NFC <a class="header-anchor" href="#configure-nfc" aria-label="Permalink to &quot;Configure NFC&quot;">​</a></h4><p>Configure NFC exactly <a href="./../use/NFC.html">like this</a>.</p><h2 id="supported-sensors" tabindex="-1">Supported sensors <a class="header-anchor" href="#supported-sensors" aria-label="Permalink to &quot;Supported sensors&quot;">​</a></h2><p>Only Libre 1 and Pro are natively supported by xDrip for NFC readings. In order to scan a Libre 14 days US or a Libre 2 Europe, you need an <a href="./../use/OOP.html">Out of Process Algorithm</a> installed on the phone.</p><table tabindex="0"><thead><tr><th style="text-align:center;">- Libre 1 / Pro -</th><th style="text-align:center;">- 14 days US -</th><th style="text-align:center;">- Libre 2/2+ EU -</th></tr></thead><tbody><tr><td style="text-align:center;"><code>Yes</code></td><td style="text-align:center;"><code>OOP2</code></td><td style="text-align:center;"><code>OOP2</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Minimum scanning interval</p><p>You should wait at least 60 seconds between two NFC scans.</p></div><br><p>Continue to <a href="./../use/startsensor.html#libre">Start Sensor</a>, remembering that you will need to scan the sensor to get initial readings.</p><br><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Last modified 6/12/2024</em></a></p>',17)])])}const f=r(n,[["render",i]]);export{m as __pageData,f as default};
